#!/usr/bin/env python3
"""Render honest current coverage and a local page-skill entry point."""
from pathlib import Path
import json,datetime,html
R=Path(__file__).resolve().parents[1]
def run():
 registry=json.loads((R/'page_skills/registry.json').read_text(encoding='utf-8'));coverage=json.loads((R/'research/live_pages/coverage.json').read_text(encoding='utf-8'));skills=registry['skills'];patterns=json.loads((R/'interaction_skills/registry.json').read_text(encoding='utf-8'))['skills'];observed=sum(s['source_coverage']=='observed_examples' for s in skills)
 rows=['# 页面专项 Skills · 整理进行中','',f'现有 24 套核心技能继续保留；新增 {len(skills)} 套可单独安装的页面技能，再新增 {len(patterns)} 套具体交互机制技能，共 {24+len(skills)+len(patterns)} 套。新增技能中 {observed} 套有当前页面来源，{len(skills)-observed} 套仍需补来源。**这不是全站已经完成的声明。**','',f'已记录 {coverage["observed_records"]} 个页面结果，其中 {coverage["observed_complete_http_dom"]} 个完整读取 HTTP DOM；已发现 {coverage["awarded_external_hosts_discovered"]} 个获奖外站主机。尚有 {coverage["queue"].get("pending",0)} 个已发现地址待观察，发现范围仍可能增长。','', '网址数用于审计来源；每套技能都有任务、页面结构、数据字段、交互状态、恢复路径、响应式、动效、版权边界、独立蓝本和验收要求。网页 DOM、浏览器视觉度量、原创蓝本测试、原站交互验证分别记录，不混为同一种完成。','', '| Skill | 页面 | 原站证据 | 指令与契约 | 原创演示 |','|---|---|---|---|---|']
 for s in skills:rows.append(f'| `{s["skill"]}` | {s["title"]} | {s["evidence_level"]} / {s["source_count"]} 来源 | [{s["id"]}]({s["path"]}/SKILL.md) | [HTML]({s["demo"]}index.html) |')
 rows+=['','## 独立交互机制 Skills','', '| Skill | 机制 | 独立指令 | 原创演示 |','|---|---|---|---|']
 for s in patterns:rows.append(f'| `{s["skill"]}` | {s["title"]} | [SKILL]({s["path"]}/SKILL.md) | [HTML]({s["demo"]}index.html) |')
 rows+=['','## 使用','', '在仓库根目录运行：','', '```text','python tools/install_all_skills.py --list','python tools/install_all_skills.py --target YOUR_SKILLS_DIRECTORY','python skills/awwwards-page-course-detail/scripts/scaffold.py --output YOUR_EMPTY_DIRECTORY','python -m http.server 4180 --bind 127.0.0.1','```','', '本地入口：http://127.0.0.1:4180/page_skills/ 。单独导出的蓝本在其目录启动静态服务即可，不需要 npm 或原站素材。已有技能目录和非空项目均不覆盖。','', '## 未完成范围','', '- 未遍历全部 Awwwards 历史获奖记录和所有外站内页；来源台账记录了当前发现范围与待处理地址。','- 来源只经过 HTTP 读取的，不算视觉或交互审计完成；浏览器显示受限、空白或尚未加载的单独记录。','- 原创蓝本经过测试也不等于原站逐像素复刻、所有隐藏状态或生产后端完成。','- 受 robots、登录、关停、访问拒绝或素材权利限制的部分继续保留缺口，不绕过或补造。','- 独立视频、物理/Shader 等机制按真实素材与环境接入后另测；画廊蓝本不冒充已包含原站视频内容。','', '实时来源：[研究覆盖](research/live_pages/coverage.json) · [页面观察](research/live_pages/sources.jsonl) · [视觉度量](research/live_pages/visual-observations.json) · [蓝本验证](research/page_skill_validation/browser-results.json)。','']
 (R/'PAGE_SKILLS.md').write_text('\n'.join(rows),encoding='utf-8',newline='\n')
 cards=[]
 for s in skills:cards.append('<article><div class="meta">'+html.escape(s['kind'])+' / '+html.escape(s['evidence_level'])+'</div><h2>'+html.escape(s['title'])+'</h2><code>'+html.escape(s['skill'])+'</code><p>'+str(s['source_count'])+' observed source references</p><a href="../'+s['demo']+'">Open original blueprint ↗</a><br><a href="../'+s['path']+'/SKILL.md">Read skill instructions</a></article>')
 for s in patterns:cards.append('<article><div class="meta">Distinct mechanism / limited source states</div><h2>'+html.escape(s['title'])+'</h2><code>'+html.escape(s['skill'])+'</code><p>Observed mechanism → original standalone implementation</p><a href="../'+s['demo']+'">Open original pattern ↗</a><br><a href="../'+s['path']+'/SKILL.md">Read pattern instructions</a></article>')
 page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page skills / Working collection</title><style>:root{font:16px/1.6 Segoe UI,Arial,sans-serif;color:#172c29;background:#f0f1e9}*{box-sizing:border-box}body{margin:0}main{max-width:1280px;margin:auto;padding:55px 5vw}h1{font:400 clamp(38px,5vw,70px)/1.05 Georgia,serif;letter-spacing:-.04em;max-width:14ch}.label,.meta{text-transform:uppercase;font-size:11px;letter-spacing:.12em;color:#275a47}.note{max-width:75ch;color:#476154}section{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin-top:36px}article{background:#fffefa;padding:24px;border:1px solid #ccd8c8;border-radius:9px;min-width:0}h2{font-size:21px}code{font-size:12px;overflow-wrap:anywhere}a{color:inherit;display:inline-block;padding:10px 0;text-underline-offset:4px}:focus-visible{outline:3px solid #a75514;outline-offset:4px}@media(max-width:900px){section{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:580px){section{grid-template-columns:1fr}main{padding:32px 18px}}</style></head><body><main><div class="label">Observed pages → reusable skills / In progress</div><h1>A page for the task at hand.</h1><p class="note">Standalone original page recipes with evidence boundaries. Sources, authored implementations and actual tests are distinct. This collection does not claim that all Awwwards pages or all awarded websites have been studied.</p><p>'''+str(len(skills))+' page skills + '+str(len(patterns))+' mechanism skills · '+str(observed)+' with observed sources · '+str(len(skills)-observed)+' still need source inspection.</p><a href="../PAGE_SKILLS.md">Coverage and installation guide ↗</a><section>'+''.join(cards)+'</section></main></body></html>'
 (R/'page_skills/index.html').write_text(page,encoding='utf-8',newline='\n')
 return {'page_skills':len(skills),'core_skills':24,'observed_source_skills':observed,'status':'in_progress'}
if __name__=='__main__':print(json.dumps(run()))
